  "Sport outside the gym. It shows in your history and calendar and tires the muscles it used, but adds no sets.": "जिम के बाहर का खेल। यह आपके इतिहास और कैलेंडर में दिखता है और इस्तेमाल हुई मांसपेशियों को थकाता है, पर सेट नहीं जोड़ता।",
  "Strava, your watch, Runna and friends: their sessions show in your calendar and tire the right muscles. No sets, no volume.": "Strava, आपकी घड़ी, Runna वगैरह: उनके सेशन आपके कैलेंडर में दिखते हैं और सही मांसपेशियाँ थकाते हैं। न सेट, न वॉल्यूम।",
