  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'एक बार इस्तेमाल होने वाला कोड आपके फ़ोन या किसी दूसरे कंप्यूटर को उसकी अपनी पासकी से साइन इन करने देता है।',
