  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'पुष्टि हो गई। अब नई पासकी बनाएँ; आपका ब्राउज़र पूछेगा कि इसे कहाँ रखना है।',
  'Copy link': 'लिंक कॉपी करें',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'इस डिवाइस पर प्रोफ़ाइल "{0}" के लिए पासकी बनाएँ। अब से आप यहाँ इसी से साइन इन करेंगे।',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'हर पासकी उस डिवाइस या पासवर्ड मैनेजर से इस प्रोफ़ाइल में साइन इन करती है जिसमें वह रखी है। नाम बदलने या हटाने के लिए किसी पर टैप करें।',
  'Enter the code from your other device.': 'अपने दूसरे डिवाइस का कोड दर्ज करें।',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'इस डिवाइस, सिक्योरिटी की, पासवर्ड मैनेजर, या ब्राउज़र के अपने QR कोड के ज़रिए आपके फ़ोन के लिए। पहले पुष्टि करें कि यह आप ही हैं।',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'इससे अब इस प्रोफ़ाइल में साइन इन नहीं हो सकेगा। जो डिवाइस इससे पहले से साइन इन है, वह साइन इन ही रहेगा। अगर वह खो गया हो, तो "हर जगह साइन आउट करें" इस्तेमाल करें।',
  'It is your only way in, so it cannot be removed until there is another.': 'यह अंदर आने का आपका एकमात्र तरीका है, इसलिए जब तक कोई दूसरा न हो, इसे हटाया नहीं जा सकता।',
  'Last used {0}': 'आख़िरी बार {0} को इस्तेमाल हुई',
