  'Name, e.g. Work laptop': 'नाम, जैसे ऑफ़िस लैपटॉप',
  'None yet. Add one and sign in without your password.': 'अभी कोई नहीं। एक जोड़ें और बिना पासवर्ड के साइन इन करें।',
