  'The next regular target continues from the last included workout.': 'अगला सामान्य लक्ष्य अंतिम शामिल वर्कआउट से जारी रहता है।',
  'Deload routine': 'डीलोड रूटीन',
  'Its workouts do not count toward progression. They still show in history and statistics.': 'इसके वर्कआउट प्रोग्रेशन में नहीं गिने जाते। वे इतिहास और आँकड़ों में दिखते रहते हैं।',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'डीलोड रूटीन यहाँ तय किए गए आँकड़ों से शुरू होता है, इसलिए ऊपर वाला प्रोग्रेशन उस पर लागू नहीं होता।',
  'Linear progression': 'रैखिक प्रोग्रेशन',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': 'डबल प्रोग्रेशन',
  'Add time': 'समय बढ़ाएँ',
  'Targets stay where you set them.': 'लक्ष्य वैसे ही रहते हैं जैसे आपने तय किए।',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'हर सेट में सभी रेप्स पूरे करें तो वज़न बढ़ता है। बार-बार चूकने पर डीलोड होता है।',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'दो सामान्य सेट और आख़िरी सेट फ़ेल्योर तक। उस सेट में लक्ष्य पार करें तो वज़न बढ़ता है (रेप्स दोगुने करें तो दोगुना)। एक बार चूकने पर 10 % घट जाता है।',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'एक ही वज़न पर रेप रेंज में ऊपर बढ़ें। हर सेट में रेंज का ऊपरी सिरा छुएँ तो वज़न बढ़ता है और रेप्स नीचे लौट आते हैं।',
  'Hold every set for the full duration and the target goes up.': 'हर सेट पूरे समय तक होल्ड करें तो लक्ष्य बढ़ जाता है।',
  'Nothing logged yet, so this session sets the baseline.': 'अभी कुछ दर्ज नहीं, इसलिए यह सेशन आधार तय करेगा।',
  'Held every set for the full time. Target goes up by {0}s.': 'हर सेट पूरे समय तक होल्ड किया। लक्ष्य {0} सेकंड बढ़ा।',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': 'लगातार {0} सेशन कम रहे। {1} सेकंड पर लौटें और फिर से बढ़ाएँ।',
  'Came up short last time. Same target again.': 'पिछली बार पूरा नहीं हुआ। वही लक्ष्य दोबारा।',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'हर सेट में रेंज का ऊपरी सिरा। {0} {1} ज़्यादा, और वापस {2} रेप्स पर।',
  'Stuck for {0} sessions. Deload to {1} {2}.': '{0} सेशन से अटके हुए। {1} {2} पर डीलोड।',
  'Same weight, aim for {0} reps this time.': 'वही वज़न, इस बार {0} रेप्स का लक्ष्य रखें।',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'आख़िरी सेट में {0} रेप्स, लक्ष्य से दोगुने! {1} {2} की दोगुनी छलांग लगाइए।',
  'Every rep last time. {0} {1} more.': 'पिछली बार सारे रेप्स पूरे। {0} {1} ज़्यादा।',
  'Every rep last time. {0} {1} less help.': 'पिछली बार हर दोहराव पूरा। {0} {1} कम सहारा।',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'हर सेट में दोहराव सीमा के शीर्ष पर। {0} {1} कम सहारा, वापस {2} दोहराव पर।',
  'Missed reps. {0} {1} of help while you build back up.': 'दोहराव छूटे। जब तक दोबारा बनाओ, तब तक {0} {1} सहारा।',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '{0} सत्र से अटके हुए। वापस {1} {2} सहारे पर, फिर से बढ़ाओ।',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'लगातार {0} सेशन रेप्स चूके। {1} {2} पर लौटें और फिर से बढ़ाएँ।',
  'Missed reps. Reset to {0} {1} and work back up.': 'रेप्स चूके। {0} {1} पर लौटें और फिर से बढ़ाएँ।',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'पिछली बार रेप्स चूके। वही वज़न दोबारा ({1} में से {0} बाकी)।',
  'Bodyweight: every rep last time, so go for {0} this time.': 'बॉडीवेट: पिछली बार सारे रेप्स पूरे, तो इस बार {0} का लक्ष्य रखें।',
  'Bodyweight: same target again until every set is clean.': 'बॉडीवेट: जब तक हर सेट साफ़ न हो, वही लक्ष्य।',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} सेट अपने साथ {1} लाते हैं। इसे देखने के लिए सेटिंग्स में “प्रति सेट मेहनत” चालू करें।',
  '{0} sets bring an {1} with them.': '{0} सेट अपने साथ {1} लाते हैं।',
