  'How hard was that set?': 'वह सेट कितना मुश्किल था?',
  'Tap how many reps you had left, or type an exact {0}.': 'टैप करें कि कितने रेप्स बाकी थे, या सटीक {0} दर्ज करें।',
  'Exact {0}': 'सटीक {0}',
  'Clear rating': 'रेटिंग साफ़ करें',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR गिनता है कि टंकी में कितने रेप्स बचे; RPE उसी मेहनत को 10 के पैमाने पर पढ़ता है, यानी RPE ≈ 10 − RIR. जिसमें आप पहले से सोचते हैं, वही चुनें।',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'हाइलाइट की गई पंक्ति वह है जहाँ ज़्यादातर वर्किंग सेट आते हैं। पहले दर्ज किए सेट अपना पैमाना बनाए रखते हैं, और इस मान को और कुछ नहीं पढ़ता, इसलिए प्रोग्रेशन और अनुमानित 1RM पर कोई असर नहीं।',
  // --- effort in the stats ---
  'Effort': 'मेहनत',
