  'Where the sets land': 'सेट कहाँ गिरते हैं',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': 'ज़्यादातर वर्किंग सेट फ़ेल्योर के पास होने चाहिए, उस पर नहीं। आधे सबसे नीचे और आधे सबसे ऊपर हों, तब भी औसत बीच में सेहतमंद-सा दिखता है।',
