  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'आपका नाम, साइन-इन विवरण और आपके खाते की बाकी सब जानकारी यहीं रहती है। दूसरों का डेटा कभी शामिल नहीं होता।',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'कोच डॉक्टर या फ़िज़ियोथेरेपिस्ट नहीं है। अगर कहीं दर्द हो तो किसी विशेषज्ञ से मिलें।',
