  'The Coach fits the volume to the time you actually have, including rest between sets.': 'कोच आपके पास वाकई उपलब्ध समय के हिसाब से वॉल्यूम तय करता है, सेटों के बीच आराम सहित।',
  'What can you train with?': 'आप किन उपकरणों से ट्रेनिंग कर सकते हैं?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'जो कुछ उपलब्ध है सब चुनें। खाली छोड़ने पर कोच पूरी लाइब्रेरी इस्तेमाल करेगा।',
  'Anything to work around?': 'कुछ ध्यान रखने योग्य?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'चोटें, तकलीफ़ देने वाले जोड़, जो मूवमेंट आप नहीं कर सकते, या व्यावहारिक सीमाएँ (जैसे फ़्लैट में सुबह 6 बजे ट्रेनिंग)।',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'जैसे “बायाँ कंधा नाज़ुक, बारबेल ओवरहेड प्रेस नहीं”',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'अगर सच में दर्द हो, तो किसी विशेषज्ञ से मिलें। कोच सावधानी से प्लान बनाएगा, पर कोई निदान नहीं कर सकता।',
  'Anything else?': 'और कुछ?',
  'Exercises you love': 'जो एक्सरसाइज़ आपको पसंद हैं',
  'e.g. “deadlifts, anything with a kettlebell”': 'जैसे “डेडलिफ़्ट, केटलबेल वाली कोई भी चीज़”',
  'Exercises you would rather not': 'जो एक्सरसाइज़ आप नहीं करना चाहेंगे',
  'e.g. “I hate lunges”': 'जैसे “मुझे लंजेज़ बिल्कुल पसंद नहीं”',
  'Anything you want the Coach to know': 'जो आप कोच को बताना चाहते हैं',
  'e.g. “I want visible arms progress by spring”': 'जैसे “वसंत तक बाहों में साफ़ फ़र्क़ चाहिए”',
  'Build my plan': 'मेरा प्लान बनाएँ',
