  'Discard this plan?': 'यह प्लान छोड़ दें?',
  'Nothing is saved, and you can ask again anytime.': 'कुछ सहेजा नहीं जाएगा, और आप कभी भी दोबारा माँग सकते हैं।',
  'Revision {0}': 'संस्करण {0}',
  'Replaces your current week. Days this plan leaves empty become rest days.': 'यह आपके मौजूदा हफ़्ते की जगह लेगा। जो दिन यह प्लान खाली छोड़ता है वे आराम के दिन बन जाएँगे।',
  'Could not apply those changes': 'वे बदलाव लागू नहीं हो सके',
  'Dismiss these suggestions?': 'ये सुझाव हटा दें?',
  'Nothing changes, and the Coach will remember you turned these down.': 'कुछ नहीं बदलेगा, और कोच याद रखेगा कि आपने इन्हें ठुकराया।',
