  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'कोच के देखने के बाद आपका प्लान बदल गया है। जो सुझाव अब मेल नहीं खाते, वे धुँधले दिख रहे हैं। उन्हें फिर से देखने के लिए नई समीक्षा माँगें।',
  'Doesn’t match your plan any more, so it can’t be applied.': 'अब आपके प्लान से मेल नहीं खाता, इसलिए लागू नहीं हो सकता।',
