  'There’s no routine to review yet. Build one with at least two exercises first.': 'अभी समीक्षा के लिए कोई रूटीन नहीं। पहले कम से कम दो व्यायामों वाला एक रूटीन बनाएँ।',
  'How should the Coach run?': 'कोच कैसे चले?',
  'List models': 'मॉडल सूची',
  'Model': 'मॉडल',
