  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'आपके सर्वर पर कोच चालू नहीं है। इसके एडमिन से पूछें, या नीचे अपनी कुंजी लगाएँ।',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'आपका सर्वर उस प्रदाता से कोच चलाता है जिसे उसके एडमिन ने सेट किया है। जो पहले से सिंक होता है उसके अलावा इस फ़ोन से कुछ नया बाहर नहीं जाता।',
