  // --- AI Coach chat ---
  'A local model can take longer.': 'स्थानीय मॉडल में अधिक समय लग सकता है।',
  'All optional. The more the Coach knows, the less it guesses.': 'सब वैकल्पिक है। कोच जितना अधिक जानेगा, उतना कम अनुमान लगाएगा।',
