  'A fresh plan from your answers; your workouts stay': 'आपके जवाबों से एक नई योजना; आपके वर्कआउट बने रहेंगे',
  'Build me a fresh plan from my answers.': 'मेरे जवाबों से मेरे लिए एक नई योजना बनाओ।',
  'Experience': 'अनुभव',
  'Goal, days, equipment, limits': 'लक्ष्य, दिन, उपकरण, सीमाएँ',
  'Have a look at my training and tell me what you would change.': 'मेरा प्रशिक्षण देखो और बताओ तुम क्या बदलोगे।',
  'Here is what I am working with:': 'मेरी स्थिति यह है:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'नमस्ते, मैं आपका कोच हूँ। मैं आपके जवाबों से आपकी योजना बनाता हूँ और जो आप सच में दर्ज करते हैं उसके हिसाब से उसे बदलता हूँ। आपके कहे बिना कुछ नहीं बदलता।',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'मैंने सब देख लिया, अभी मैं कुछ नहीं बदलूँगा। ऐसे ही लगे रहें, और कुछ और सत्रों के बाद फिर पूछें।',
  'I understand, let’s go': 'समझ गया, चलिए',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': 'आयात हो गया! {0} रूटीन आपकी योजना में हैं और आपका सप्ताह सेट है। अगले सत्र में मिलते हैं।',
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': 'आयात हो गया! {0} रूटीन आपकी योजना में हैं। आपका सप्ताह वैसा ही है; जब चाहें उन्हें शेड्यूल करें।',
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'यह कुछ उत्तरों से आपकी योजना बनाता है और आपके वास्तविक रिकॉर्ड के आधार पर उसे समायोजित करता है। आपकी अनुमति के बिना कुछ नहीं बदलता, और हर बदलाव को पूर्ववत किया जा सकता है।',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'रूटीन, व्यायाम, सेट और रेप्स, आपका साप्ताहिक कार्यक्रम और प्रगति सेटिंग।',
  'Your logged training': 'आपकी दर्ज ट्रेनिंग',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'समीक्षा अवधि में आपके दर्ज किए सेट: वज़न, रेप्स, समय, मेहनत की रेटिंग, सेशन कितनी देर चले, और आपके सेशन के नोट।',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'उसी अवधि के वज़न मापन, और आपका लक्ष्य वज़न, अगर आपने तय किया है।',
  'What you tell the Coach': 'आप कोच को क्या बताते हैं',
