  'Imported! {0} routines are in your plan and your rotation starts over with them. See you at the next session.': 'आयात हो गया! {0} रूटीन आपकी योजना में हैं और आपका रोटेशन इन्हीं से फिर शुरू होता है। अगले सत्र में मिलते हैं।',
