  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'ज़्यादातर काम हो गया। एक-दो सेट कम रहे, जो एक बार चलता है। संकेत तभी है जब अगली बार भी वही सेट छूटें।',
