  'The Coach couldn’t run. The instance owner needs to check its setup.': 'कोच चल नहीं सका। इंस्टेंस स्वामी को इसका सेटअप जाँचना होगा।',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'कोच अपने AI प्रदाता की सीमा तक पहुँच गया। बाद में फिर कोशिश करें, नहीं तो इंस्टेंस स्वामी को प्लान या कुंजी जाँचनी होगी।',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'कोच के AI प्रदाता ने अनुरोध का प्रारूप अस्वीकार कर दिया। इंस्टेंस स्वामी को कोई दूसरा मॉडल आज़माना होगा।',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'कोच का AI प्रदाता अभी बंद है। थोड़ी देर में फिर कोशिश करें।',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'कोच अपने AI प्रदाता तक नहीं पहुँच सका। इंस्टेंस स्वामी को एंडपॉइंट और नेटवर्क जाँचना होगा।',
  'The Coach answered with something the app couldn’t use.': 'कोच ने ऐसा जवाब दिया जिसे ऐप इस्तेमाल नहीं कर सकता।',
  'The server restarted while the Coach was thinking.': 'कोच के सोचते समय सर्वर रीस्टार्ट हो गया।',
  'The Coach couldn’t read your training data.': 'कोच आपका प्रशिक्षण डेटा नहीं पढ़ सका।',
  'The Coach is switched off on this instance for safety reasons.': 'सुरक्षा कारणों से इस इंस्टेंस पर कोच बंद है।',
  'Something went wrong on the server.': 'सर्वर पर कुछ गड़बड़ हो गई।',
  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'आपके AI प्रदाता ने इस फ़ोन की कुंजी अस्वीकार कर दी। इसे सेटिंग्स → AI कोच में जाँचें।',
  'The Coach isn’t set up on this phone. Check Settings → AI Coach.': 'इस फ़ोन पर कोच सेट नहीं है। सेटिंग्स → AI कोच देखें।',
  'Your AI provider couldn’t answer.': 'आपका AI प्रदाता जवाब नहीं दे सका।',
  'Something went wrong on this phone.': 'इस फ़ोन पर कुछ गड़बड़ हो गई।',
  'Coach week': 'कोच का सप्ताह',
  'Your loop': 'आपका चक्र',
