  'Add to the rotation': 'रोटेशन में जोड़ें',
  'No rotation yet. Add routines in the order you want to train them. The first one you haven’t logged stays up next.': 'अभी कोई रोटेशन नहीं। रूटीन को उसी क्रम में जोड़ें जिसमें आप उन्हें ट्रेन करना चाहते हैं। जिसे आपने अभी तक लॉग नहीं किया, वही अगला बना रहता है।',
  'Use this rotation': 'इस रोटेशन का उपयोग करें',
  'Use this rotation?': 'इस रोटेशन का उपयोग करें?',
  'Your own loop gets replaced.': 'आपका अपना चक्र बदल दिया जाएगा।',
  'Your coach gives up control of this week: openGym owns the queue from here on and repeats these sessions by itself once they are all done. A new week from the coach’s app would replace this rotation.': 'आपका कोच इस सप्ताह का नियंत्रण छोड़ देता है: अब से यह कतार openGym की है और वह सभी सत्र पूरे होते ही उन्हें अपने आप दोहराता है। कोच के ऐप से आया कोई नया सप्ताह इस रोटेशन की जगह ले लेगा।',
  'Start new pass': 'नया पास शुरू करें',
  'This rotation couldn’t be read. Another device may have written it.': 'यह रोटेशन पढ़ा नहीं जा सका। हो सकता है इसे किसी दूसरे डिवाइस ने लिखा हो।',
  'Discard it': 'इसे हटा दें',
  'Use Fixed Week': 'नियत सप्ताह का उपयोग करें',
  'No rotation yet. Add routines to it in Plan.': 'अभी कोई रोटेशन नहीं। योजना में इसमें रूटीन जोड़ें।',
  'Set up in Plan': 'योजना में सेट करें',
