  'A different rep target for each set, e.g. 12 · 8 · 6 · Max · 12.': 'हर सेट के लिए अलग रेप लक्ष्य, जैसे 12 · 8 · 6 · मैक्स · 12।',
  'Max': 'मैक्स',
