  'Set {0} ({1})': 'सेट {0} ({1})',
  '{0} set becomes {1}: one on each side, {2}s held every time.': '{0} सेट {1} बन जाता है: हर तरफ़ एक, हर बार {2} सेकंड होल्ड।',
  '{0} sets become {1}: one on each side, {2}s held every time.': '{0} सेट {1} बन जाते हैं: हर तरफ़ एक, हर बार {2} सेकंड होल्ड।',
  'For side planks, single-arm holds and the like. Trains each side on its own.': 'साइड प्लैंक, एक हाथ से होल्ड और ऐसे व्यायामों के लिए। हर तरफ़ को अलग से ट्रेन करता है।',
  'Compare photos': 'फ़ोटो की तुलना करें',
  'Photo': 'फ़ोटो',
  'Pick two photos to compare.': 'तुलना के लिए दो फ़ोटो चुनें।',
  'Progress photos': 'प्रोग्रेस फ़ोटो',
  'Ready! Open the comparison.': 'तैयार! तुलना खोलें।',
