  'The last set goes until nothing is left, and counts as all-out effort unless you rate it.': 'आख़िरी सेट तब तक चलता है जब तक कुछ न बचे, और जब तक आप ख़ुद रेट न करें, इसे पूरी ताक़त वाला प्रयास माना जाता है।',
