  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'जवाब देने के लिए कोच यह आपके openGym सर्वर के ज़रिए {0} को भेजता है, जो openGym से बाहर की एक AI सेवा है और जिसे आपके सर्वर के एडमिन ने चुना है:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'जवाब देने के लिए यह डिवाइस इसे आपकी API कुंजी के साथ सीधे {0} को भेजता है, जो openGym से बाहर की एक AI सेवा है:',
  'Who may see your training': 'आपकी ट्रेनिंग कौन देख सकता है',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'इस डिवाइस से कोच आपकी ट्रेनिंग किसे भेज सकता है। अनुमति वापस लेने पर कोच अगली बार फिर पूछेगा। आपके अपने नेटवर्क के मॉडल के लिए कभी पूछने की ज़रूरत नहीं।',
