  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'आपका फ़ोन जाँचेगा कि यह आप हैं (चेहरा, फ़िंगरप्रिंट या पासकोड), फिर खाता हट जाएगा।',
