  // --- reading back from Health Connect / Apple Health (v1.4.3) ---
  'Heart rate from your watch': 'आपकी घड़ी से धड़कन',
  'After a workout, each set gets the heart rate your watch saved. Garmin, Fitbit, Galaxy Watch and friends welcome.': 'वर्कआउट के बाद हर सेट को वह धड़कन मिलती है जो आपकी घड़ी ने सहेजी। Garmin, Fitbit, Galaxy Watch और बाकी सबका स्वागत है।',
  'Weigh-ins from other apps': 'दूसरे ऐप्स से वज़न',
  'Your smart scale’s weigh-ins land here. One you type in yourself always wins.': 'आपके स्मार्ट स्केल का वज़न यहाँ आ जाता है। जो आप खुद लिखते हैं, वही हमेशा जीतता है।',
  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last 30 days. Older workouts stay as they are.': 'openGym सिर्फ़ तब पढ़ता है जब वह खुला हो: पिछले एक दिन के वर्कआउट की धड़कन, पिछले 30 दिन का वज़न। पुराने वर्कआउट जैसे हैं वैसे ही रहते हैं।',
  // --- gym reminder (#614) ---
  'A nudge when you walk into your gym.': 'जिम में घुसते ही एक छोटा सा इशारा।',
  'Add a gym': 'जिम जोड़ें',
  'All the time': 'हर समय अनुमति दें',
  'Allow location “All the time”?': 'लोकेशन को “हर समय अनुमति दें”?',
  'Allow location “Always”?': 'लोकेशन को “हमेशा” अनुमति दें?',
  'Always': 'हमेशा',
  'Finding you…': 'आपको ढूँढ रहे हैं…',
  'Gym reminder': 'जिम रिमाइंडर',
  'Checking if you made it to the gym': 'देख रहे हैं कि आप जिम पहुँचे या नहीं',
  'Quick arrival check': 'जल्दी पहुँचने की जाँच',
  'Near a gym, the phone takes a short GPS look (a few minutes at most) so the nudge comes at the door.': 'जिम के पास फ़ोन थोड़ी देर GPS से देख लेता है (ज़्यादा से ज़्यादा कुछ मिनट), ताकि याद दिलाना दरवाज़े पर ही आ जाए।',
  'Android can take up to half an hour to notice you walked in. Set openGym’s battery use to Unrestricted and the phone takes a short GPS look when you get near a gym, so the nudge comes at the door.': 'Android को यह पता चलने में आधा घंटा तक लग सकता है कि आप पहुँच गए। openGym का बैटरी इस्तेमाल Unrestricted कर दें, तो जिम के पास फ़ोन थोड़ी देर GPS से देख लेगा और याद दिलाना दरवाज़े पर आएगा।',
  'Gym spotted': 'जिम दिख गया',
  'Leave it empty for the default.': 'डिफ़ॉल्ट टेक्स्ट के लिए खाली छोड़ें।',
  'Location access': 'लोकेशन एक्सेस',
  'Location isn’t allowed for openGym. You can change that in the phone’s settings.': 'openGym को लोकेशन की अनुमति नहीं है। इसे फ़ोन की सेटिंग्स में बदल सकते हैं।',
  'My gym': 'मेरा जिम',
  'Name': 'नाम',
  'No more nudges when you arrive here.': 'यहाँ पहुँचने पर अब कोई इशारा नहीं।',
  'Not asked yet': 'अभी पूछा नहीं गया',
  'Nothing found. Try a street and a town.': 'कुछ नहीं मिला। कोई गली और शहर आज़माएँ।',
  'Notification text': 'नोटिफ़िकेशन टेक्स्ट',
  'Notifications are off for openGym, so the reminder has nowhere to show up.': 'openGym के नोटिफ़िकेशन बंद हैं, इसलिए रिमाइंडर कहीं दिख नहीं सकता।',
  'On the next screen, pick “Allow all the time”.': 'अगली स्क्रीन पर “हर समय अनुमति दें” चुनें।',
  'Only between certain hours': 'सिर्फ़ कुछ घंटों में',
  'Only while using the app': 'सिर्फ़ ऐप इस्तेमाल करते समय',
  'Outside these hours the phone stays quiet, even at the gym.': 'इन घंटों के बाहर फ़ोन चुप रहता है, जिम में भी।',
  'Radius': 'दायरा',
  'Ready for your workout? 💪': 'वर्कआउट के लिए तैयार? 💪',
  'Remove this gym?': 'यह जिम हटाएँ?',
  'Search': 'खोजें',
  'Searching…': 'खोज रहे हैं…',
  'That’s 20 gyms, the most a phone can watch.': 'यह 20 जिम हो गए, फ़ोन इससे ज़्यादा नहीं देख सकता।',
  'The phone itself watches the gyms you added and only wakes openGym when you arrive. No tracking in between, and your locations never leave this phone.': 'आपके जोड़े गए जिम पर फ़ोन खुद नज़र रखता है और आपके पहुँचने पर ही openGym को जगाता है। बीच में कोई ट्रैकिंग नहीं, और आपकी जगहें कभी इस फ़ोन से बाहर नहीं जातीं।',
  'The reminder needs location access in the background. You can allow it in the phone’s settings.': 'रिमाइंडर को बैकग्राउंड में लोकेशन चाहिए। इसे फ़ोन की सेटिंग्स में अनुमति दे सकते हैं।',
  'To notice that you walked into your gym while openGym is closed, the phone needs to let it see your location in the background.': 'openGym बंद होने पर भी आपके जिम में घुसने का पता चले, इसके लिए फ़ोन को उसे बैकग्राउंड में आपकी लोकेशन देखने देनी होगी।',
  'Until': 'तक',
  'Walk into one of your gyms and openGym nudges you to hit Start. Once a day at most, and never when you already trained. Your gyms stay on this phone.': 'अपने किसी जिम में घुसिए और openGym आपको स्टार्ट दबाने का इशारा करेगा। दिन में ज़्यादा से ज़्यादा एक बार, और अगर आप ट्रेनिंग कर चुके हैं तो कभी नहीं। आपके जिम इसी फ़ोन पर रहते हैं।',
  'Without background location the phone can’t spot your gym while openGym is closed.': 'बैकग्राउंड लोकेशन के बिना openGym बंद होने पर फ़ोन आपका जिम नहीं पहचान सकता।',
  'Your gyms': 'आपके जिम',
  '{0} m': '{0} मी.',
  'Precise location is off for openGym. Turn it on in the phone’s settings, or your gym can’t be spotted.': 'openGym के लिए सटीक लोकेशन बंद है। इसे फ़ोन की सेटिंग्स में चालू करें, वरना आपका जिम पहचाना नहीं जा सकता।',
