  'Same as last week, a bit heavier': 'पिछले हफ़्ते जैसा, थोड़ा भारी',
  'Share programme': 'प्रोग्राम शेयर करें',
  'Start programme': 'प्रोग्राम शुरू करें',
  'Start “{0}”?': '"{0}" शुरू करें?',
  'Starter programmes': 'स्टार्टर प्रोग्राम',
  'Strength block, 4 weeks': 'स्ट्रेंथ ब्लॉक, 4 हफ़्ते',
  'The schedule in your plan right now becomes this programme’s.': 'आपके प्लान में अभी जो शेड्यूल है, वही इस प्रोग्राम का बन जाता है।',
  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': 'हफ़्ता कैलेंडर का हफ़्ता है: हफ़्ता 1 वह है जिसमें आप शुरू करते हैं। रोकने पर यह थमा रहता है।',
  'This programme is gone.': 'यह प्रोग्राम अब नहीं है।',
  'Three days of plain linear progression, with a deload every fourth week.': 'तीन दिन सीधा लीनियर प्रोग्रेशन, हर चौथे हफ़्ते डीलोड के साथ।',
  'Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.': 'तीन दिन 5×5 रूटीन पर, हर हफ़्ते थोड़ा भारी, फिर तरोताज़ा होने के लिए एक हल्का हफ़्ता।',
  'Upper / lower by effort, 6 weeks': 'अपर / लोअर मेहनत के हिसाब से, 6 हफ़्ते',
  'Use my current plan': 'मेरा मौजूदा प्लान लें',
  'Week 1 starts now. Have fun!': 'हफ़्ता 1 अभी शुरू। मज़े कीजिए!',
