  'Your routines as a block of weeks, each week with its own %1RM or RPE.': 'आपके रूटीन हफ़्तों के एक ब्लॉक की तरह, हर हफ़्ते अपने %1RM या RPE के साथ।',
  'Your routines as a block of weeks, with starter programmes to try.': 'आपके रूटीन हफ़्तों के एक ब्लॉक की तरह, आज़माने के लिए स्टार्टर प्रोग्राम के साथ।',
