  "No thanks": "नहीं, धन्यवाद",
  "Pick an exercise to see its best sets, estimated max and where it’s heading.": "कोई व्यायाम चुनिए: सबसे अच्छे सेट, अनुमानित अधिकतम और रुझान देखिए।",
  "Pointing at: {0}": "इस पर संकेत: {0}",
  "Practice run": "अभ्यास सेशन",
  "Programmes and sharing": "प्रोग्राम और शेयरिंग",
  "Programmes, starter plans and sharing a plan with a friend live behind this button.": "प्रोग्राम, स्टार्टर प्लान और दोस्त से प्लान शेयर करना, सब इस बटन के पीछे है।",
  "Records": "रिकॉर्ड",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "शेड्यूल बताता है कब, रूटीन बताता है क्या। अपने बनाइए या स्टार्टर प्लान लीजिए।",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "आपकी भाषा में हज़ारों व्यायाम। पसंदीदा पर स्टार लगाइए, वे ऊपर आ जाएँगे।",
  "See which muscles got the work and which still need rest. Tap one for details.": "देखिए किन मांसपेशियों ने काम किया और किन्हें अभी आराम चाहिए। विवरण के लिए किसी एक पर टैप कीजिए।",
  "Show me": "दिखाइए",
  "Show the tour again": "टूर फिर से दिखाएँ",
