  "Step {0} of {1}": "चरण {0} / {1}",
  "Swipe a set": "सेट स्वाइप कीजिए",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "किसी सेट को बगल में स्वाइप करके कॉपी या हटाइए। उसका नंबर और भी खोलता है।",
  "The big Start button": "बड़ा शुरू बटन",
  "The little body shows what each day works, so leg day can’t hide.": "छोटा शरीर दिखाता है कि हर दिन क्या काम करता है, लेग डे छिप नहीं सकता।",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "आराम अपने आप शुरू होता है। समय जोड़िए, या हीरो वाला मूड हो तो छोड़ दीजिए।",
  "The ⋯ menu": "⋯ मेनू",
  "Theme, accent colour and what Home shows.": "थीम, एक्सेंट रंग और होम पर क्या दिखे।",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "यह बस अभ्यास है, कुछ सेव नहीं होगा। हर पंक्ति एक सेट है: वज़न, फिर रेप्स। बदलने के लिए किसी नंबर पर टैप कीजिए।",
  "Tick it off": "टिक कीजिए",
  "Today at a glance": "एक नज़र में आज",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "आज का सेशन यहाँ है। एक टैप और आप उठा रहे हैं। आराम के दिन यही लिखा होगा, बिना किसी अपराध-बोध के।",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "तय दिनों पर ट्रेन कीजिए, या रूटीन को लूप में चलाइए जहाँ अगला आपका इंतज़ार करे।",
  "Want a 1-minute tour?": "1 मिनट का टूर लेंगे?",
  "Week or rotation": "हफ़्ता या रोटेशन",
  "We’ll point at the good bits on the real screens. Bail out anytime.": "हम असली स्क्रीन पर काम की चीज़ें दिखाएँगे। जब चाहें बाहर निकलिए।",
  "Workout settings, layouts, notes and extra exercises hide in here.": "वर्कआउट सेटिंग्स, लेआउट, नोट्स और अतिरिक्त व्यायाम यहाँ छिपे हैं।",
  "Workouts, streaks and everything you’ve lifted. It fills up as you train.": "वर्कआउट, स्ट्रीक और आपने जो कुछ उठाया। ट्रेनिंग के साथ भरता जाता है।",
  "You stopped halfway. Want to see the rest?": "आप बीच में रुक गए थे। बाकी देखेंगे?",
