  'A small picture next to each exercise, like a plan from the gym.': 'हर एक्सरसाइज़ के पास एक छोटी तस्वीर, जिम से मिले प्लान की तरह।',
  // --- Settings → Integrations (1.4.4) ---
  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "यह फ़ोन वाले openGym ऐप में है: iPhone पर Apple Health, Android पर Health Connect।",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Webhook आपका अपना openGym सर्वर भेजता है, इसलिए सर्वर चाहिए। खाता में इस डिवाइस को उससे जोड़ें।",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "इस सर्वर पर webhook बंद हैं। उसकी .env में INTEGRATIONS=webhook जोड़ें और रीस्टार्ट करें।",
  "The MCP server runs next to your own openGym server and reads your data there.": "MCP सर्वर आपके openGym सर्वर के साथ चलता है और वहीं आपका डेटा पढ़ता है।",
  "Only what you switch on talks to anything. The rest stays out of your way.": "सिर्फ़ वही बाहर बात करता है जो आप चालू करें। बाकी आपके रास्ते में नहीं आता।",
  "Could not reach your server": "आपके सर्वर तक नहीं पहुँच सके",
  "Tap to try again": "फिर से कोशिश करने के लिए टैप करें",
  "Disconnect {0}?": "{0} डिस्कनेक्ट करें?",
  "openGym stops writing and reading. What it already wrote can stay there as your data, or go.": "openGym लिखना और पढ़ना बंद कर देगा। जो पहले लिखा जा चुका है वह आपके डेटा के रूप में रह सकता है या हट सकता है।",
  "Works with": "इनके साथ चलता है",
  "No extra connection needed: they write to {0}, and openGym reads from there.": "अलग कनेक्शन की ज़रूरत नहीं: ये {0} में लिखते हैं और openGym वहीं से पढ़ता है।",
  "No extra connection needed: they write to Apple Health or Health Connect, and the openGym phone app reads from there.": "अलग कनेक्शन की ज़रूरत नहीं: ये Apple Health या Health Connect में लिखते हैं और फ़ोन वाला openGym ऐप वहीं से पढ़ता है।",
  "{0} has no direct line to openGym, and it does not need one.": "{0} का openGym से सीधा कनेक्शन नहीं है, और ज़रूरत भी नहीं।",
  "How it gets here": "यहाँ कैसे आता है",
  "{0} saves to Apple Health on iPhone or Health Connect on Android. openGym reads from there.": "{0} iPhone पर Apple Health में या Android पर Health Connect में सेव करता है। openGym वहीं से पढ़ता है।",
  "What openGym reads": "openGym क्या पढ़ता है",
  "What it does not do": "यह क्या नहीं करता",
  "Workouts logged in openGym go to the health store, not back into {0} itself.": "openGym में दर्ज वर्कआउट हेल्थ स्टोर में जाते हैं, वापस {0} में नहीं।",
  "Set up {0}": "{0} सेट अप करें",
  "Install the openGym app on your phone to use this.": "इसे इस्तेमाल करने के लिए फ़ोन पर openGym ऐप इंस्टॉल करें।",
