  "Paste the URL from Home Assistant, n8n, ntfy or similar. Your home network works too.": "Home Assistant, n8n, ntfy या ऐसे किसी टूल का URL पेस्ट करें। घर का नेटवर्क भी चलेगा।",
  "Paste the HTTPS URL from Home Assistant, n8n, ntfy or similar.": "Home Assistant, n8n, ntfy या ऐसे किसी टूल का HTTPS URL पेस्ट करें।",
