  "This lives in the openGym phone app.": "यह फ़ोन वाले openGym ऐप में है।",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "आपकी घड़ी या वज़न मशीन भी यहाँ लिखती है? Garmin, COROS, Fitbit, Withings, Oura और बाकी इसी रास्ते openGym तक आते हैं।",
