  "AI & API": "AI और API",
  "Workouts and weigh-ins out, heart rate and scale readings in.": "वर्कआउट और वज़न बाहर, हार्ट रेट और स्केल की रीडिंग अंदर।",
  "Finished workouts and weigh-ins go to Apple Health.": "पूरे हुए वर्कआउट और वज़न Apple Health में जाते हैं।",
  "Heart rate from your watch fills in each set.": "आपकी घड़ी का हार्ट रेट हर सेट में भरता है।",
