  "Reads the export file of another app, once.": "किसी दूसरे ऐप की एक्सपोर्ट फ़ाइल एक बार पढ़ता है।",
  "Exercises are matched to the library, you check the rest.": "एक्सरसाइज़ लाइब्रेरी से मिलाई जाती हैं, बाकी आप जाँचें।",
  "Spreadsheet (CSV)": "स्प्रेडशीट (CSV)",
  "Every set, weigh-in and measurement, for Excel and friends.": "हर सेट, वज़न और माप, Excel जैसे टूल के लिए।",
  "One row per set, plus body weight and measurements.": "हर सेट की एक पंक्ति, साथ में शरीर का वज़न और माप।",
  "openGym can read it back in later.": "openGym बाद में इसे फिर पढ़ सकता है।",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "वर्कआउट ख़त्म होने पर Home Assistant, n8n या ntfy को बताएँ।",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "वर्कआउट ख़त्म होने, रिकॉर्ड टूटने या वज़न करने पर एक साइन किया हुआ JSON संदेश।",
  "Sent by your server, from whichever device you logged on.": "आपका सर्वर भेजता है, चाहे आपने किसी भी डिवाइस पर दर्ज किया हो।",
  "Plans and reviews from the model you pick.": "आपके चुने मॉडल से प्लान और समीक्षा।",
  "Reads your plan and the last weeks of training when you ask.": "पूछने पर आपका प्लान और पिछले कुछ हफ़्तों की ट्रेनिंग पढ़ता है।",
  "Set up on its own page.": "इसके अपने पेज पर सेट होता है।",
  "MCP server": "MCP सर्वर",
  "Let Claude Desktop, Cursor and friends read your training log.": "Claude Desktop, Cursor जैसे टूल को अपना ट्रेनिंग लॉग पढ़ने दें।",
