  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "खिंचाव है, तो बाकी हल्का। अगर अब भी दर्द हो तो रुक जाएँ।",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "खिंचाव है, इसलिए बचे सेट ऐसे मूवमेंट पर जाएँगे जो उसी मांसपेशी को नरम कोण से काम कराता है।",
