  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "लॉग किए गए सेट और आपका रूटीन जैसे हैं वैसे रहेंगे। कोच डॉक्टर या फ़िज़ियोथेरेपिस्ट नहीं है। कहीं दर्द हो तो किसी विशेषज्ञ से पूछें।",
