  "Nothing to change. Carry on as planned.": "बदलने को कुछ नहीं। योजना के अनुसार जारी रखें।",
  "One set less keeps the session doable today and still counts.": "एक सेट कम करने से आज का सेशन हो जाएगा और फिर भी गिना जाएगा।",
