  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "ऐप आपके वर्क वेट से सीढ़ी बनाता है: भारी हो तो ज़्यादा वार्म-अप, हल्का हो तो कम, आपके जिम की प्लेटों पर।",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "रैक खाली नहीं है, तो इसे आख़िर में करें। बाकी सेशन को इसकी ज़रूरत नहीं।",
  "There’s no workout running.": "कोई वर्कआउट नहीं चल रहा।",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "ये वार्म-अप हर सेशन में वर्क सेट से पहले आते हैं, वर्क वेट के हिस्से के रूप में, इसलिए उसके साथ बढ़ते हैं।",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "यह डेमो है, इसलिए मेरे पीछे कोई AI मॉडल नहीं है। आपके अपने सर्वर पर मैं आपका सेशन पढ़कर ऐसे बदलाव सुझाता हूँ।",
