  "Just training": "बस ट्रेनिंग",
  "Log sets from your wrist on an Apple Watch, Wear OS, Garmin or Zepp watch.": "Apple Watch, Wear OS, Garmin या Zepp घड़ी पर कलाई से ही सेट दर्ज करें।",
  "Log, plan, progress. Nothing else on the screen.": "दर्ज करें, प्लान करें, आगे बढ़ें। स्क्रीन पर और कुछ नहीं।",
  "Logging, plans, history, the exercise library and the basic stats are always on.": "दर्ज करना, प्लान, इतिहास, एक्सरसाइज़ लाइब्रेरी और बुनियादी आँकड़े हमेशा चालू रहते हैं।",
  "Modules": "मॉड्यूल",
  "Motivation": "प्रेरणा",
  "Plates and warm-ups": "प्लेटें और वार्म-अप",
  "Plus weigh-ins, measurements, photos and your health apps.": "साथ में वज़न मापन, माप, फ़ोटो और आपके हेल्थ ऐप।",
  "Rate each set in RIR or RPE, and see in Stats how hard you really push.": "हर सेट को RIR या RPE में रेट करें, और आँकड़े में देखें कि आप असल में कितना ज़ोर लगाते हैं।",
  "Reviews your training and suggests changes. You still say yes or no.": "आपकी ट्रेनिंग देखता है और बदलाव सुझाता है। हाँ या ना अब भी आप ही कहते हैं।",
  "Scheduled Coach reviews take a break while the AI Coach is off. Your setup and chats stay.": "AI कोच बंद रहने तक तय कोच रिव्यू छुट्टी पर रहते हैं। आपका सेटअप और चैट बने रहते हैं।",
  "Start from": "यहाँ से शुरू करें",
  "Streaks, challenges, badges, recaps and your year in openGym.": "स्ट्रीक, चैलेंज, बैज, सार और openGym में आपका साल।",
  "Streaks, the Coach, themes, the lot.": "स्ट्रीक, कोच, थीम, सब कुछ।",
  "Switch off": "बंद करें",
  "Switch off what you don’t use. Nothing gets deleted: switch it back on and it’s all still there.": "जो इस्तेमाल नहीं करते, उसे बंद कर दें। कुछ भी डिलीट नहीं होता: फिर से चालू करें और सब वहीं मिलेगा।",
  "Switch off {0}?": "{0} बंद करें?",
  "Switch these off?": "इन्हें बंद करें?",
  "The plates to load under every set, and warm-ups that build themselves.": "हर सेट के लिए कौन-सी प्लेटें लगानी हैं, और अपने-आप बनने वाले वार्म-अप।",
  "Training": "ट्रेनिंग",
