  "Webhooks for Home Assistant and friends, and the MCP server.": "Home Assistant और साथियों के लिए Webhook, और MCP सर्वर।",
  "Weigh-ins, measurements, progress photos and your weight goal.": "वज़न मापन, माप, प्रोग्रेस फ़ोटो और आपका वज़न लक्ष्य।",
  "Your membership codes on Home, and NFC stickers that start a workout.": "होम पर आपके सदस्यता कोड, और वर्कआउट शुरू करने वाले NFC स्टिकर।",
