  "Up to 30 seconds, from an MP3, M4A, WAV or OGG file. Silence at either end is trimmed off.": "30 सेकंड तक, MP3, M4A, WAV या OGG फ़ाइल से। दोनों सिरों की चुप्पी काट दी जाती है।",
