  "That did not work. Try again in a moment.": "यह नहीं हुआ। थोड़ी देर में फिर कोशिश करें।",
  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "यह फ़ाइल यहाँ कभी शेयर नहीं की जा सकती। बिल्ट-इन लाइब्रेरी की तस्वीरें और एनिमेशन लाइसेंस वाले हैं।",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "इस फ़ाइल में अभी भी लोकेशन जैसी छिपी जानकारी है। ऐप में इसे फिर से जोड़ें और नई कॉपी शेयर करें।",
  "That is not shared any more.": "यह अब शेयर नहीं है।",
  "That one is not in the community any more.": "यह अब कम्युनिटी में नहीं है।",
  "That one is yours.": "यह आपका है।",
  "That sound did not come through.": "वह आवाज़ नहीं पहुँची।",
  "That tip did not come through.": "वह सुझाव नहीं पहुँचा।",
  "The sharing text changed. Have a quick read and try again.": "शेयरिंग का टेक्स्ट बदल गया है। एक बार जल्दी से पढ़ें और फिर कोशिश करें।",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "यह इस सर्वर पर सबके लिए सार्वजनिक है: यहाँ जिसका भी अकाउंट है, वह इसे देख सकता है, आज़मा सकता है और कॉपी कर सकता है। आपका नाम और तारीख हमेशा इसके साथ जाते हैं। सिर्फ़ वही शेयर करें जो आपका है: जो आपने बनाया, रिकॉर्ड किया या जिसे आगे देने का आपको हक़ है। बिल्ट-इन लाइब्रेरी की व्यायाम तस्वीरें और एनिमेशन लाइसेंस वाले हैं और कभी शेयर नहीं किए जा सकते। आप कभी भी शेयर करना बंद कर सकते हैं; दूसरों ने जो कॉपी पहले ही ले ली हैं, वे उनके पास रहती हैं।",
  "This kind of item cannot be taken.": "इस तरह की चीज़ ली नहीं जा सकती।",
  "This server has no community library.": "इस सर्वर पर कोई कम्युनिटी लाइब्रेरी नहीं है।",
