  "This profile is linked to your {0} account, so signing in there signs you in here.": "यह प्रोफ़ाइल आपके {0} खाते से लिंक है: वहाँ साइन इन हैं तो यहाँ भी हैं।",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "यह सर्वर सिर्फ़ न्योते से है और अकेले {0} से अंदर नहीं आ सकते। इसे चलाने वाले से पूछें।",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "इस सर्वर पर सब {0} से साइन इन करते हैं। नए हैं? साइन इन करते ही आपकी प्रोफ़ाइल बन जाएगी।",
