  "or use a pairing code": "या पेयरिंग कोड इस्तेमाल करें",
  "{0} could not be reached. Try again in a moment.": "{0} तक नहीं पहुँच पाए। थोड़ी देर में फिर कोशिश करें।",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} इस प्रोफ़ाइल में आने का अकेला रास्ता है, इसलिए यह लिंक रहेगा। पहले एक पासकी जोड़ें।",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} ने आपको अंदर आने दिया, पर यह सर्वर सिर्फ़ कुछ ग्रुप लेता है। इसे चलाने वाले से आपको जोड़ने को कहें।",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} ने ऐसा कुछ लौटाया जिसे हम जाँच नहीं पाए, इसलिए कोई साइन इन नहीं हुआ। अगर बार-बार हो, तो एडमिन पेज पर वजह दिखती है।",
