  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "{0} के लिए तय सेट फ़िट नहीं हुए, इसलिए रूटीन के अपने सेट लगे हैं: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "आज के सेट {0} से हैं। आपका रूटीन वैसा ही रहता है।",
  "Today’s rows were planned for this day. Your routine stays as it is.": "आज के सेट इसी दिन के लिए तय किए गए थे। आपका रूटीन वैसा ही रहता है।",
  "Body composition from your scale": "आपके स्केल से शरीर की संरचना",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "बॉडी फैट और लीन मास, जैसा आपके स्केल ने सेव किया। बॉडी माप में दिखते हैं, आपकी अपनी एंट्री में कभी नहीं मिलते।",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "बॉडी फैट, लीन मास, हड्डियों का भार, शरीर का पानी और BMR, जैसा आपके स्केल ने सेव किया। बॉडी माप में दिखते हैं, आपकी अपनी एंट्री में कभी नहीं मिलते।",
  "From Health Connect": "Health Connect से",
  "From Apple Health": "Apple Health से",
  "Lean mass": "लीन मास",
  "Bone mass": "हड्डियों का भार",
  "Body water": "शरीर का पानी",
