  "A token lets one program, like an AI assistant, see or change only what you tick. Never more than you can, and only your own profile.": "टोकन किसी एक प्रोग्राम, जैसे AI असिस्टेंट, को सिर्फ़ वही देखने या बदलने देता है जो आप चुनें। आपसे ज़्यादा कभी नहीं, और सिर्फ़ आपकी अपनी प्रोफ़ाइल।",
  "API token": "API टोकन",
  "API tokens": "API टोकन",
  "Add it as a custom connector in your AI assistant, with a token from below.": "इसे अपने AI असिस्टेंट में कस्टम कनेक्टर की तरह जोड़ें, नीचे के एक टोकन के साथ।",
  "After a year": "एक साल बाद",
  "After {0} days": "{0} दिन बाद",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "अभी कॉपी करें: openGym इसे बस इसी बार दिखाता है। इसे पासवर्ड की तरह संभालें।",
  "Ends": "ख़त्म",
