  "See reads. Change directly also writes, over the exact version it read.": "देखें सिर्फ़ पढ़ता है। सीधे बदलें लिखता भी है, ठीक उसी वर्शन पर जो उसने पढ़ा।",
  "Starts with": "शुरुआत",
