  "Compare {0} photos": "{0} फ़ोटो की तुलना करें",
  "Last photo: {0} day ago. Same spot, same light?": "पिछली फ़ोटो: {0} दिन पहले। वही जगह, वही रोशनी?",
  "Last photo: {0} days ago. Same spot, same light?": "पिछली फ़ोटो: {0} दिन पहले। वही जगह, वही रोशनी?",
  "A buzz for each phase": "हर फ़ेज़ पर एक वाइब्रेशन",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "सब कुछ की एक कॉपी, दिन में एक बार, आपके अपने फ़ोल्डर में: Nextcloud, ownCloud, कोई NAS, जो भी WebDAV बोलता हो। आपका सर्वर, किसी और का नहीं।",
  "A sound for each kind of rest": "हर तरह के आराम के लिए अलग आवाज़",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "जिस दिन भी आपने ट्रेनिंग की, उस पर एक टिक, कितने सेट हुए उसके साथ। प्लान की तरह, इसे सिर्फ़ आप देखते हैं।",
  "A tone for each phase": "हर फ़ेज़ के लिए अलग टोन",
