  "Calendar feed off": "कैलेंडर फ़ीड बंद",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "कार्डियो वैसे ही जाता है जैसा था: दौड़, राइड, रोइंग। स्ट्रेंथ वेट ट्रेनिंग के रूप में, हर सेट डिस्क्रिप्शन में।",
  "Change server or password": "सर्वर या पासवर्ड बदलें",
  "Check the connection": "कनेक्शन जाँचें",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "ब्राउज़र में अपने सर्वर पर साइन इन करके openGym से Strava को एक बार कनेक्ट करें। फिर आपके वर्कआउट सर्वर से जाते हैं, चाहे आप उन्हें किसी भी डिवाइस पर दर्ज करें।",
  "Connected. Your first backup goes up now.": "कनेक्ट हो गया। आपका पहला बैकअप अभी जा रहा है।",
  "Disconnect Strava?": "Strava डिस्कनेक्ट करें?",
  "Disconnect WebDAV?": "WebDAV डिस्कनेक्ट करें?",
  "Explosive lift (X)": "विस्फोटक लिफ़्ट (X)",
  "Folder address": "फ़ोल्डर का पता",
  "Get set": "तैयार हो जाइए",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "जेब में ही जान लें कि रुकना है, सुपरसेट की शुरुआत पर लौटना है या आगे बढ़ना है।",
  "Last backup {0}": "आख़िरी बैकअप {0}",
