  "Things the list has no word for. Your own exercises that need them show only here.": "वो चीज़ें जिनका सूची में कोई नाम नहीं। इनकी ज़रूरत वाले आपके अपने व्यायाम सिर्फ़ यहीं दिखते हैं।",
  "Three sets, from {0} up to {1} reps. Every set at {1} and the next rung is yours.": "तीन सेट, {0} से {1} रेप्स तक। हर सेट {1} पर और अगला पायदान आपका।",
