  "When your numbers dip two weeks running (and your check-ins say tired, if you log them), Home asks.": "जब आपके आँकड़े लगातार दो हफ़्ते गिरें (और आपके चेक-इन थकान बताएँ, अगर आप उन्हें लॉग करते हैं), तो होम पूछेगा।",
