  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "आप बीमार थे, इसलिए यह हफ़्ता माफ़ है। स्ट्रीक चलती रही और कोई फ़्रीज़ खर्च नहीं हुआ।",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "आप सफ़र में थे, इसलिए यह हफ़्ता माफ़ है। स्ट्रीक चलती रही और कोई फ़्रीज़ खर्च नहीं हुआ।",
