  "{1} is still recovering, so it sits this one out.": "{1} अभी रिकवर हो रही है, इसलिए इस बार यह आराम करेगी।",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "और ऐसा ही रहेगा: openGym Offline के पास इंटरनेट की अनुमति नहीं है, तो Android उसकी हर कोशिश रोक देता है।",
  "Any of the sounds on your phone.": "आपके फ़ोन की कोई भी आवाज़।",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "समय-समय पर सेटिंग्स, डेटा और बैकअप में बैकअप लें। फ़ोन पर रखी फ़ाइल ही इकलौती कॉपी है।",
  "Closing the app resets the count; the log never leaves the phone.": "ऐप बंद करने से गिनती शून्य हो जाती है; लॉग कभी फ़ोन से बाहर नहीं जाता।",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "{0} से गिनती, जब ऐप शुरू हुआ। बंद करने पर शून्य; लॉग कभी फ़ोन से बाहर नहीं जाता।",
  "Each reminder can sound different, so you know which one it is before you look.": "हर रिमाइंडर की अलग आवाज़ हो सकती है, ताकि देखने से पहले ही पता चल जाए कौन सा है।",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "इस ऐप ने इंटरनेट से जो कुछ माँगा, नया पहले। सिर्फ़ पता, सामग्री कभी नहीं।",
  "For reading mid-set without your glasses.": "सेट के बीच बिना चश्मे के पढ़ने के लिए।",
  "Larger": "और बड़ा",
  "Last at {0}": "आख़िरी बार {0}",
  "Latest": "हाल के",
  "Less: no sliding, bouncing or snow. Things just appear.": "कम: कोई फिसलन, उछाल या बर्फ़ नहीं। चीज़ें बस दिख जाती हैं।",
  "Like the phone": "फ़ोन जैसा",
  "Mostly your own server, {0}, when there was something to sync.": "ज़्यादातर आपका अपना सर्वर, {0}, जब कुछ सिंक करना था।",
