  "Network log": "नेटवर्क लॉग",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offline में नक्शे पर खोज नहीं है। अपने जिम में खड़े हों, मौजूदा स्थान दबाएँ, हो गया।",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "इस फ़ोन से एक भी बाइट बाहर नहीं गया। आपकी ट्रेनिंग आपके सिवा किसी का काम नहीं।",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "अभी कुछ नहीं। जब कुछ सिंक करना हो, तब आपका सर्वर इस फ़ोन से सुनता है।",
