  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline कभी अपडेट नहीं खोजता, खोज ही नहीं सकता। नए वर्शन वहीं मिलेंगे जहाँ से यह मिला।",
