  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "कुछ देर से कुछ दर्ज नहीं। अगर हो गया, तो यह {0} पर अपने आप खत्म होगा, आखिरी सेट पर सेव।",
  "Forgotten workouts": "भूले हुए वर्कआउट",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "अगर कोई जवाब न दे, तो यह अपने आप खत्म होता है और कभी कुछ नहीं फेंकता। अंत आपका आखिरी सेट और उसका आराम है, ताकि समय सही रहे। इतिहास से एक दिन तक दोबारा खोल सकते हैं। आपकी घड़ी भी पूछती है।",
  "Never asks and never ends one by itself.": "कभी नहीं पूछता और कभी अपने आप खत्म नहीं करता।",
  "The default. Long enough for a chat at the water fountain.": "डिफ़ॉल्ट। वाटर कूलर पर गपशप के लिए काफ़ी।",
