  "Lock Screen, notification, the workout card": "लॉक स्क्रीन, सूचना, वर्कआउट कार्ड",
  "Long-press view": "लंबा दबाने पर दृश्य",
  "Minimal": "न्यूनतम",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "iOS 17 या नया चाहिए। लॉक स्क्रीन पर एनिमेशन नहीं होते, इसलिए एक्सरसाइज़ की तस्वीर स्थिर है। बटन बिना अनलॉक किए चलते हैं, समाप्त ऐप खोलता है।",
  "No buttons. A tap on it opens openGym.": "कोई बटन नहीं। टैप करने पर openGym खुलता है।",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "लॉक स्क्रीन पर जगह नहीं बची। Apple लाइव एक्टिविटी को लगभग 160 पॉइंट ऊँचा रखता है।",
  "No tiles yet.": "अभी कोई टाइल नहीं।",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "यहाँ अभी कुछ नहीं, इसलिए वर्कआउट स्क्रीन जैसी है वैसी रहेगी। एक टाइल जोड़ो या प्रीसेट चुनो।",
  "Opens openGym, since saving asks what to keep.": "openGym खोलता है, क्योंकि सेव करते समय पूछा जाता है कि क्या रखना है।",
  "Six tiles fit in a notification before it starts mumbling.": "एक सूचना में छह टाइलें आती हैं, उसके बाद वह बड़बड़ाने लगती है।",
  "Size of {0}": "{0} का आकार",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island में चार टाइलें आती हैं। यह एक द्वीप है, महाद्वीप नहीं।",
  "The pill": "पिल",
  "The pill has two spots, one each side of the camera.": "पिल में दो जगहें हैं, कैमरे के दोनों ओर एक-एक।",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "पिल कैमरे के पास दो टाइलें दिखाता है। बाकी के लिए लंबा दबाओ।",
  "The widget fits three lines under the set.": "विजेट में सेट के नीचे तीन पंक्तियाँ आती हैं।",
  "Three buttons fit in the Dynamic Island.": "Dynamic Island में तीन बटन आते हैं।",
  "Tiles": "टाइलें",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "टाइलें टेक्स्ट की पंक्तियाँ बन जाती हैं, ताकि Android 16 इसे घड़ी के पास Live Update बनाए रख सके। आराम के दौरान सूचना अपने आराम वाले बटन दिखाती है।",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "सेट के नीचे तीन पंक्तियों तक। विजेट अपने − और + बटन रखता है।",
  "Where it shows": "कहाँ दिखे",
  "Work set": "वर्क सेट",
  "Zone {0}": "ज़ोन {0}",
  "{0} layout on.": "{0} लेआउट चालू।",
  "Exercise picture": "एक्सरसाइज़ की तस्वीर",
  "Target": "लक्ष्य",
  "Incline": "ढलान",
  "Resistance": "प्रतिरोध",
  "Band": "बैंड",
